'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const {chromium}=require('playwright');
const ORIGIN=process.env.FORMATX_TEST_URL||'https://formatxsuite.com/';
const OUT=process.env.FORMATX_MAG_EVIDENCE_DIR||'artifacts/live-mag-functional';
const CANVAS='#hero .hero-space > .fx-crystal-organism-r326-stage > .fx-crystal-organism-r326-canvas';
const ASK='#hero .fx-reference-ask',PAUSE='#hero .fx-reference-pause';
fs.mkdirSync(OUT,{recursive:true});
const write=(n,v)=>fs.writeFileSync(path.join(OUT,n),JSON.stringify(v,null,2));
async function state(page){return page.evaluate(({CANVAS,PAUSE})=>{const c=document.querySelector(CANVAS),r=c?.getBoundingClientRect(),s=c?getComputedStyle(c):null;window.__fxIds||=new WeakMap();window.__fxSeq||=0;const animations=c?.getAnimations?.().map(a=>{if(!window.__fxIds.has(a))window.__fxIds.set(a,`a${++window.__fxSeq}`);return{id:window.__fxIds.get(a),name:String(a.animationName||''),time:typeof a.currentTime==='number'?a.currentTime:null,playState:String(a.playState||''),pending:Boolean(a.pending)};})||[];return{renderer:document.documentElement.dataset.fxCoreRenderer||'',shapeSync:document.documentElement.dataset.fxMagShapeSyncR476||'',motionContract:document.documentElement.dataset.fxPrimaryMagMotionContractR528||'',canvasCount:document.querySelectorAll(CANVAS).length,pauseCount:document.querySelectorAll(PAUSE).length,size:{w:r?.width||0,h:r?.height||0},display:s?.display||'',visibility:s?.visibility||'',animations,overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth};},{CANVAS,PAUSE});}
const ids=s=>s.animations.map(a=>`${a.id}:${a.name}`).sort();
function advance(a,b){const m=new Map(a.animations.map(x=>[x.id,x]));return Math.max(0,...b.animations.map(x=>{const p=m.get(x.id);return typeof x.time==='number'&&typeof p?.time==='number'?x.time-p.time:0;}));}
async function waitReady(page){await page.waitForFunction(sel=>document.documentElement.dataset.fxCrystalOrganismR326==='ready'&&document.querySelectorAll(sel).length===1,CANVAS,{timeout:60000});}
async function verifyNormal(browser,name,viewport,mobile){const context=await browser.newContext({viewport,isMobile:mobile,hasTouch:mobile,deviceScaleFactor:mobile?2:1,locale:'hu-HU',reducedMotion:'no-preference'});const page=await context.newPage(),errors=[],failed=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error'&&!/WebGL|GPU|favicon/i.test(m.text()))errors.push(m.text());});page.on('requestfailed',r=>{if(!/cloudflareinsights|favicon/i.test(r.url()))failed.push(`${r.method()} ${r.url()}`);});try{await page.goto(`${ORIGIN}${ORIGIN.includes('?')?'&':'?'}mag-r528=${name}-${Date.now()}`,{waitUntil:'domcontentloaded',timeout:60000});const target=page.locator('#hero .fx-reference-mag-button, #hero .fx-reference-ask, #hero .fx-mag-heart-hit-r252').first();await target.waitFor({state:'visible',timeout:30000});await target.click().catch(()=>{});await waitReady(page);const a=await state(page);await page.waitForTimeout(400);const b=await state(page);assert.equal(a.canvasCount,1);assert.equal(b.canvasCount,1);assert.equal(b.pauseCount,0,`${name}: obsolete PAUSE returned`);assert.equal(b.renderer,'single-webgl-crystal-organism-r326');assert.match(b.motionContract,/living-core-normal-continuous-reduced-background-safe/);assert.ok(b.size.w>220&&b.size.h>220,`${name}: canvas too small`);assert.deepEqual(ids(b),ids(a),`${name}: animation identity changed`);const delta=advance(a,b);assert.ok(delta>16,`${name}: living motion did not advance ${delta}`);const ask=page.locator(ASK).first();assert.equal(await ask.isVisible(),true,`${name}: ASK missing`);const box=await ask.boundingBox();assert.ok(box&&box.width>=44&&box.height>=44,`${name}: ASK hit invalid`);await ask.click();await page.waitForTimeout(120);const c=await state(page);assert.equal(c.canvasCount,1,`${name}: ASK duplicated renderer`);const gl=await page.locator(CANVAS).evaluate(canvas=>{const x=canvas.getContext('webgl2')||canvas.getContext('webgl');return{has:Boolean(x),error:x?x.getError():-1};});assert.equal(gl.has,true);assert.equal(gl.error,0);assert.ok(c.overflow<=2);assert.equal(errors.length,0,errors.join(' | '));assert.equal(failed.length,0,failed.join(' | '));return{name,renderer:b.renderer,motionAdvanceMs:delta,size:b.size,ask:{w:box.width,h:box.height},gl};}finally{await context.close();}}
async function fallback(browser){const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});await context.addInitScript(()=>{const o=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(t,...a){if(['webgl','webgl2','experimental-webgl'].includes(t))return null;return o.call(this,t,...a);};});const page=await context.newPage();try{await page.goto(`${ORIGIN}?mag-r528-fallback=${Date.now()}`,{waitUntil:'domcontentloaded',timeout:60000});await page.waitForTimeout(2200);const s=await page.evaluate(PAUSE=>({hero:Boolean(document.querySelector('#hero')),lead:(document.querySelector('#hero .hero-lead')?.textContent||'').trim().length,pauseCount:document.querySelectorAll(PAUSE).length,overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth}),PAUSE);assert.ok(s.hero&&s.lead>40);assert.equal(s.pauseCount,0);assert.ok(s.overflow<=2);return s;}finally{await context.close();}}
async function reduced(browser){const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,reducedMotion:'reduce'});const page=await context.newPage();try{await page.goto(`${ORIGIN}?mag-r528-reduced=${Date.now()}`,{waitUntil:'domcontentloaded',timeout:60000});await page.waitForTimeout(4000);const s=await page.evaluate(PAUSE=>({scheduler:document.documentElement.dataset.fxP0MotionSchedulerR490||'',hero:Boolean(document.querySelector('#hero')),lead:(document.querySelector('#hero .hero-lead')?.textContent||'').trim().length,core:Boolean(document.querySelector('.fx-reference-mag-button')),pauseCount:document.querySelectorAll(PAUSE).length,overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth}),PAUSE);assert.ok(s.hero&&s.lead>40&&s.core);assert.equal(s.pauseCount,0);assert.match(s.scheduler,/reduced-motion-static|armed|committed/);assert.ok(s.overflow<=2);return s;}finally{await context.close();}}
(async()=>{const browser=await chromium.launch({headless:true,args:['--use-angle=swiftshader','--enable-webgl','--ignore-gpu-blocklist','--enable-unsafe-swiftshader','--disable-dev-shm-usage']});try{const report={auditedSha:process.env.AUDITED_SHA||'',url:ORIGIN,contract:'r528-living-core-no-manual-pause',desktop:await verifyNormal(browser,'desktop',{width:1440,height:900},false),mobile:await verifyNormal(browser,'mobile',{width:390,height:844},true),fallback:await fallback(browser),reducedMotion:await reduced(browser)};write('report.json',report);console.log(JSON.stringify(report,null,2));}finally{await browser.close();}})().catch(e=>{write('report-failure.json',{auditedSha:process.env.AUDITED_SHA||'',url:ORIGIN,error:String(e?.stack||e)});console.error(e?.stack||e);process.exit(1);});
